# ---------------------------------------------------------------------------
# Methods whose coefficients depend on a parameter (perform_step! of
# Anas5ConstantCache in fixed_timestep_perform_step.jl, FRK65ConstantCache
# in low_order_rk_perform_step.jl, and pRRK22, pRRK33, pRRK54 with
# _prrk*_coeffs in OrdinaryDiffEqSSPRK/src/ssprk_perform_step.jl).

#' Explicit Runge-Kutta methods with a parameter
#'
#' `Anas5(w)` is Anastassi's fifth order method tuned to the frequency `w`
#' of an oscillatory problem; `FRK65(omega)` the adaptive sixth order fitted
#' method of Medvedev and coworkers, exact for the frequency `omega`;
#' `pRRK22(kappa)`, `pRRK33(kappa)` and `pRRK54(kappa)` the parametric
#' relaxation SSP methods of Liu, Burchard, Kuzmin and Shang based on SSPRK22,
#' SSPRK33 and SSPRK54, stabilized by `kappa` (`kappa = 0` gives the base
#' method). All take the limiters of [explicit_rk_methods].
#'
#' @param w,omega Frequencies.
#' @param kappa Stabilization parameter.
#' @param stage_limiter,step_limiter,thread See [explicit_rk_methods].
#' @return An algorithm object.
#' @examples
#' prob <- ODEProblem(function(u, p, t) c(u[2], -u[1]), c(0, 1), c(0, 10))
#' solve(prob, Anas5(w = 1), dt = 0.1)(10)
#' solve(prob, FRK65(omega = 1))(10)
#' solve(ODEProblem(function(u, p, t) -u, 1, c(0, 1)), pRRK33(kappa = 0.5), dt = 0.1)(1)
#' @name parametric_rk_methods
NULL

.erkx_alg <- function(name, order, adaptive, step, stage_limiter, step_limiter, fsal = TRUE, ...)
  .new_alg(name, order, adaptive = adaptive, step = step,
           interp = if (fsal) .hermite_interp else .sde_linear_interp,
           init = function(ctx, t, u) list(), step_limiter = step_limiter, stage_limiter = stage_limiter, ...)

.lim <- function(lim, u, p, t) if (is.null(lim)) u else lim(u, NULL, p, t)

#' @rdname parametric_rk_methods
#' @export
Anas5 <- function(w = 1, stage_limiter = NULL, step_limiter = NULL, thread = NULL) {
  C <- .ERK_EXTRA$Anas5
  step <- function(ctx, t, u, dt, cache) {
    f <- ctx$f; p <- ctx$p
    v <- w * dt
    a43 <- C$a43
    a65 <- (-8000 / 1071) * (-a43 * v^5 + 6 * tan(v) * v^4 + 24 * v^3 - 72 * tan(v) * v^2 - 144 * v + 144 * tan(v)) /
      (v^5 * (a43 * tan(v) * v + 12 - 10 * a43))
    a61 <- C$a61 + (-119 / 200) * a65
    a63 <- C$a63 + (189 / 100) * a65
    a64 <- C$a64 + (-459 / 200) * a65
    k1 <- cache$fsal %||% f(u, p, t)
    k2 <- f(.lim(stage_limiter, u + dt * C$a21 * k1, p, t + C$c2 * dt), p, t + C$c2 * dt)
    k3 <- f(.lim(stage_limiter, u + dt * (C$a31 * k1 + C$a32 * k2), p, t + C$c3 * dt), p, t + C$c3 * dt)
    # OrdinaryDiffEq writes the a43 coefficient as 2
    k4 <- f(.lim(stage_limiter, u + dt * (C$a41 * k1 + C$a42 * k2 + 2 * k3), p, t + C$c4 * dt), p, t + C$c4 * dt)
    k5 <- f(.lim(stage_limiter, u + dt * (C$a51 * k1 + C$a52 * k2 + C$a53 * k3 + C$a54 * k4), p, t + C$c5 * dt),
            p, t + C$c5 * dt)
    k6 <- f(.lim(stage_limiter, u + dt * (a61 * k1 + C$a62 * k2 + a63 * k3 + a64 * k4 + a65 * k5), p, t + C$c6 * dt),
            p, t + C$c6 * dt)
    unew <- u + dt * (C$b1 * k1 + C$b3 * k3 + C$b4 * k4 + C$b5 * k5 + C$b6 * k6)
    k7 <- f(unew, p, t + dt)
    list(u = unew, k = list(k1, k7), cache = list(fsal = k7), nf = 6L)
  }
  .erkx_alg("Anas5", 5, FALSE, step, stage_limiter, step_limiter, w = w)
}

#' @rdname parametric_rk_methods
#' @export
FRK65 <- function(omega = 0, stage_limiter = NULL, step_limiter = NULL, thread = NULL) {
  C <- .ERK_EXTRA$FRK65
  step <- function(ctx, t, u, dt, cache) {
    f <- ctx$f; p <- ctx$p
    nsq <- (omega * dt)^2
    with(C, {
      b4 <- (d1 + nsq * (d2 + nsq * (d3 + nsq * (d4 + nsq * (d5 + nsq * (d6 + nsq * d7)))))) /
        (1 + nsq * (d8 + nsq * (d9 + nsq * (d10 + nsq * (d11 + nsq * (d12 + nsq * d13))))))
      b5 <- (e1 + nsq * (e2 + nsq * (e3 + nsq * (e4 + nsq * (e5 + nsq * e6))))) /
        (1 + nsq * (e8 + nsq * (e9 + nsq * (e10 + nsq * e11))))
      b6 <- (f1 + nsq * (f2 + nsq * (f3 + nsq * (f4 + nsq * (f5 + nsq * f6))))) /
        (1 + nsq * (f8 + nsq * (f9 + nsq * (f10 + nsq * f11))))
      k1 <- cache$fsal %||% f(u, p, t)
      st <- function(x, c) f(.lim(stage_limiter, x, p, t + c * dt), p, t + c * dt)
      k2 <- st(u + alpha21 * dt * k1, c2)
      k3 <- st(u + alpha31 * dt * k1 + alpha32 * dt * k2, c3)
      k4 <- st(u + alpha41 * dt * k1 + alpha43 * dt * k3, c4)
      k5 <- st(u + alpha51 * dt * k1 + alpha53 * dt * k3 + alpha54 * dt * k4, c5)
      k6 <- st(u + alpha61 * dt * k1 + alpha63 * dt * k3 + alpha64 * dt * k4 + alpha65 * dt * k5, c6)
      k7 <- st(u + alpha71 * dt * k1 + alpha73 * dt * k3 + alpha74 * dt * k4 + alpha75 * dt * k5 + alpha76 * dt * k6, c7)
      k8 <- st(u + alpha81 * dt * k1 + alpha83 * dt * k3 + alpha84 * dt * k4 + alpha85 * dt * k5 + alpha86 * dt * k6 +
                 alpha87 * dt * k7, c8)
      unew <- u + dt * (beta1 * k1 + b4 * k4 + b5 * k5 + b6 * k6 + beta7 * k7 + beta8 * k8)
      k9 <- f(unew, p, t + dt)
      err <- dt * (beta1tilde * k1 + (b4 - beta4tilde) * k4 + (b5 - beta5tilde) * k5 + (b6 - beta6tilde) * k6 +
                     beta7tilde * k7 + beta8tilde * k8 + beta9tilde * k9)
      list(u = unew, err = err, k = list(k1, k9), cache = list(fsal = k9), nf = 8L)
    })
  }
  .erkx_alg("FRK65", 6, TRUE, step, stage_limiter, step_limiter, adaptive_order = 5, omega = omega)
}

.prrk_coeffs <- function(z, a, b) {
  # a, b: the Shu-Osher alpha and beta of the stages, rows i = 1..s, columns j = 0..s-1
  s <- nrow(a)
  psi <- numeric(s); ah <- a * 0; bh <- b * 0; ch <- numeric(s)
  psiprev <- c(1, numeric(s))
  for (i in seq_len(s)) {
    tot <- 0
    for (j in 0:(i - 1)) if (a[i, j + 1L] != 0 || b[i, j + 1L] != 0) tot <- tot + psiprev[j + 1L] * (a[i, j + 1L] + z * b[i, j + 1L])
    psi[i] <- tot; psiprev[i + 1L] <- tot
    for (j in 0:(i - 1)) {
      ah[i, j + 1L] <- psiprev[j + 1L] * (a[i, j + 1L] + z * b[i, j + 1L]) / tot
      bh[i, j + 1L] <- psiprev[j + 1L] * b[i, j + 1L] / tot
    }
    cc <- c(0, ch)
    ch[i] <- sum(ah[i, seq_len(i)] * cc[seq_len(i)]) + sum(bh[i, seq_len(i)])
  }
  list(a = ah, b = bh, c = ch)
}

# u_i = sum_j ahat_ij u_j + dt_hat sum_j bhat_ij f(u_j), dt_hat = c_s dt
.prrk_alg <- function(name, order, A, B, kappa, stage_limiter, step_limiter) {
  step <- function(ctx, t, u, dt, cache) {
    f <- ctx$f; p <- ctx$p
    co <- .prrk_coeffs(kappa * dt, A, B)
    s <- nrow(A)
    dth <- co$c[s] * dt
    us <- list(u); ks <- list(f(u, p, t))
    cs <- c(0, co$c)
    for (i in seq_len(s)) {
      v <- 0 * u
      for (j in seq_len(i)) {
        if (co$a[i, j] != 0) v <- v + co$a[i, j] * us[[j]]
        if (co$b[i, j] != 0) v <- v + co$b[i, j] * dth * ks[[j]]
      }
      if (i < s) v <- .lim(stage_limiter, v, p, t + cs[i + 1L] * dth)
      us[[i + 1L]] <- v
      if (i < s) ks[[i + 1L]] <- f(v, p, t + cs[i + 1L] * dth)
    }
    list(u = us[[s + 1L]], k = NULL, cache = list(), nf = s)
  }
  .erkx_alg(name, order, FALSE, step, stage_limiter, step_limiter, fsal = FALSE, kappa = kappa)
}

#' @rdname parametric_rk_methods
#' @export
pRRK22 <- function(kappa = 0, stage_limiter = NULL, step_limiter = NULL, thread = NULL) {
  A <- rbind(c(1, 0), c(1 / 2, 1 / 2)); B <- rbind(c(1, 0), c(0, 1 / 2))
  .prrk_alg("pRRK22", 2, A, B, kappa, stage_limiter, step_limiter)
}

#' @rdname parametric_rk_methods
#' @export
pRRK33 <- function(kappa = 0, stage_limiter = NULL, step_limiter = NULL, thread = NULL) {
  A <- rbind(c(1, 0, 0), c(3 / 4, 1 / 4, 0), c(1 / 3, 0, 2 / 3)); B <- rbind(c(1, 0, 0), c(0, 1 / 4, 0), c(0, 0, 2 / 3))
  .prrk_alg("pRRK33", 3, A, B, kappa, stage_limiter, step_limiter)
}

