# ---------------------------------------------------------------------------
# SSP multistep methods (perform_step! of SSPRKMSVS32ConstantCache and
# SSPRKMSVS43ConstantCache): fixed step, started with Heun steps.

#' SSP multistep methods
#'
#' `SSPRKMSVS32()` and `SSPRKMSVS43()` are the strong stability preserving
#' multistep methods of order 2 (three steps) and 3 (four steps) of
#' OrdinaryDiffEqSSPRK, started with two and three Heun steps; they take
#' fixed steps (`dt`). Both take the limiters of [explicit_rk_methods].
#'
#' @inheritParams parametric_rk_methods
#' @return An algorithm object.
#' @examples
#' prob <- ODEProblem(function(u, p, t) -u, 1, c(0, 1))
#' solve(prob, SSPRKMSVS43(), dt = 0.01)(1)
#' @name ssp_multistep
NULL

.msvs_init <- function(ctx, t, u) {
  e <- new.env(parent = emptyenv())
  e$step <- 1L
  e$fsal <- ctx$f(u, ctx$p, t)
  e
}

#' @rdname ssp_multistep
#' @export
SSPRKMSVS32 <- function(stage_limiter = NULL, step_limiter = NULL, thread = NULL) {
  step <- function(ctx, t, u, dt, cache) {
    f <- ctx$f; p <- ctx$p
    fs <- cache$fsal
    if (cache$step < 3L) {
      # the starting procedure evaluates the first stage at t + dt, as in Julia
      k <- f(u, p, t + dt)
      v <- u + dt * k
      k <- f(v, p, t + dt)
      unew <- (u + v + dt * k) / 2
      if (cache$step == 1L) cache$u_2 <- u else cache$u_1 <- u
      nf <- 2L
    } else {
      Om <- 2
      unew <- (Om^2 - 1) / Om^2 * (u + Om / (Om - 1) * dt * fs) + 1 / Om^2 * cache$u_2
      cache$u_2 <- cache$u_1
      cache$u_1 <- u
      nf <- 0L
    }
    f1 <- f(unew, p, t + dt)
    cache$fsal <- f1
    cache$step <- cache$step + 1L
    list(u = unew, k = list(fs, f1), cache = cache, nf = nf + 1L)
  }
  .new_alg("SSPRKMSVS32", 2, adaptive = FALSE, step = step, interp = .hermite_interp, init = .msvs_init,
           stage_limiter = stage_limiter, step_limiter = step_limiter, ssp_coefficient = 0.5)
}

#' @rdname ssp_multistep
#' @export
SSPRKMSVS43 <- function(stage_limiter = NULL, step_limiter = NULL, thread = NULL) {
  step <- function(ctx, t, u, dt, cache) {
    f <- ctx$f; p <- ctx$p
    fs <- cache$fsal
    nf <- 0L
    if (cache$step < 4L) {
      v <- u + dt * fs
      k <- f(v, p, t + dt)
      unew <- (u + v + dt * k) / 2
      nf <- 1L
      if (cache$step == 1L) { cache$u_3 <- u; cache$k3 <- f(u, p, t + dt); nf <- nf + 1L }
      if (cache$step == 2L) { cache$u_2 <- u; cache$k2 <- f(u, p, t + dt); nf <- nf + 1L }
      if (cache$step == 3L) { cache$u_1 <- u; cache$k1 <- f(u, p, t + dt); nf <- nf + 1L }
    } else {
      unew <- (16 / 27) * (u + 3 * dt * fs) + (11 / 27) * (cache$u_3 + (12 / 11) * dt * cache$k3)
      cache$k3 <- cache$k2; cache$k2 <- cache$k1; cache$k1 <- fs
      cache$u_3 <- cache$u_2; cache$u_2 <- cache$u_1; cache$u_1 <- u
    }
    f1 <- f(unew, p, t + dt)
    cache$fsal <- f1
    cache$step <- cache$step + 1L
    list(u = unew, k = list(fs, f1), cache = cache, nf = nf + 1L)
  }
  .new_alg("SSPRKMSVS43", 3, adaptive = FALSE, step = step, interp = .hermite_interp, init = .msvs_init,
           stage_limiter = stage_limiter, step_limiter = step_limiter, ssp_coefficient = 0.33)
}
